mapper.select:
SELECT ds.id, ds.source_key, ds.source_type, ds.environment, ds.schema_version, ds.status, ds.last_success_at
FROM data_source ds WHERE 
ORDER BY ds.id LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE source_mapping SET status='approved', approved_by=#{approvedBy}, reviewed_by=#{approvedBy}, reviewed_at=UTC_TIMESTAMP(3), updated_at=CURRENT_TIMESTAMP(3)
WHERE id=#{mappingId} AND status IN ('draft', 'pending')
  AND requested_by IS NOT NULL AND requested_by <> #{approvedBy}
